var t={about:{title:"Tietoja kartasta",hiking:"<p>Tämä kartta näyttää viitoitettuja vaellusreittejä ympäri maailman.</p>\n",cycling:"<p>Tämä kartta näyttää viitoitettuja pyöräilyreittejä ympäri maailman.</p>\n",mtb:"<p>Tämä kartta näyttää viitoitettuja maastopyöräilyreittejä ympäri maailman.</p>\n",skating:"<p>Tämä kartta näyttää viitoitettuja rullaluistelureittejä ympäri maailman.</p>\n",riding:"<p>Tämä kartta näyttää viitoitettuja ratsastusreittejä ympäri maailman.</p>\n",slopemap:"<p>Tämä kartta osoittaa viitoitettuja talviurheilurinteitä ympäri maailmaa.</p>\n",osm:'<p>Reitit sijoitetaan OpenStreetMapin peruskarttatason tai vaihtoehtoisesti rinnevarjostuskarttatason päälle. Reittikartta luodaan <a href="https://www.openstreetmap.org">OpenStreetMap</a> (OSM)-projektin tiedoista. OSM on vapaasti muokattava maailmankartta, jonka muokkaamiseen kuka tahansa voi osallistua. Tämä tarkoittaa, ettei se missään nimessä ole täydellinen, mutta myös sitä, että sinäkin voit osallistua lisäämällä uusia reittejä ja korjaamalla virheitä olemassa olevissa reiteissä. Lisätietoja OpenStreetMapista löydät <a href="https://wiki.openstreetmap.org/wiki/Beginners%27_Guide">Aloittelijan oppaasta</a>.</p>\n'},rendering:{title:"OSM-datan renderöinti",hikingroutes:'<p>Vaellusreitit pitää OSM-järjestelmään syöttää relaatioina. Tämä on selitetty yksityiskohtaisemmin <a href="https://wiki.openstreetmap.org/wiki/Walking_Routes">vaellusreitit</a>-sivulla OSM-wikissä. Tämä kartta näyttää relaatiot joihin on liitetty vähintään seuraavat tagit:</p>\n<pre><code>type = route|superroute\nroute = foot|walking|hiking\n</code></pre>\n'},route_order:{title:"Reittien järjestäminen"},hierarchies:{title:"Relaatioiden hierarkiat"},osmc:{title:"osmc:symbol-tagi"},hikinglocal:{title:"Lokalisoitu renderöinti"},elevationprofiles:{title:"Korkeusprofiilit"},technical:{title:"Tekniset tiedot"},legal:{title:"Oikeudelliset- ja käyttöehdot"},acknowledgements:{title:"Kiitokset",text:'<p>Kaikki kartta-aineisto on saatu <a href="http://www.openstreetmap.org">OpenStreetMapista ja osallistujilta</a>\nja aineistoa levitetään ODbL-lisenssillä.</p>\n'},contact:{title:"Ota yhteyttä",text:'<p>Kysymykset ja kommentit tähän sivuun liittyen voidaan lähettää osoitteeseen: <a href="mailto:lonvia@denofr.de">lonvia@denofr.de</a>.</p>\n<p>Bugeista voi myös raportoida <a href="https://github.com/waymarkedtrails/waymarked-trails-site/issues">the project\'s issue tracker on github</a>. Ennen bugeista raportointia, varmista että ongelmasi ei ole OSM-datassa.</p>\n'}},i=t.about,a=t.rendering,e=t.route_order,n=t.hierarchies,s=t.osmc,r=t.hikinglocal,o=t.elevationprofiles,l=t.technical,p=t.legal,m=t.acknowledgements,k=t.contact;export{i as about,m as acknowledgements,k as contact,t as default,o as elevationprofiles,n as hierarchies,r as hikinglocal,p as legal,s as osmc,a as rendering,e as route_order,l as technical};
